$('#inlineEditor').addEventListener('input',e=>{const m=selectedMarkup();if(m&&state.editing===m.id){m.text=e.target.value;m.modified=new Date().toISOString()}});$('#inlineEditor').addEventListener('blur',finishInlineEdit);$('#inlineEditor').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finishInlineEdit()}e.stopPropagation()});function finishInlineEdit(){const m=selectedMarkup(),ed=$('#inlineEditor');if(m&&state.editing===m.id)m.text=ed.value;state.editing=null;ed.classList.add('hidden');renderMarkups();renderTable()}
function addStamp(text,assetData=null,assetAspect=null){const b=viewportCenterOnPage();let w=190,h=44;if(assetData){const a=Math.max(.2,Math.min(5,Number(assetAspect)||2));w=150;h=Math.max(45,Math.min(120,w/a))}addMarkup({type:'stamp',x:b.x-w/2,y:b.y-h/2,w,h,text,assetData,assetAspect,subject:text,comment:'',status:'Open',stroke:assetData?'#666666':(text.startsWith('TTC')?'#d66b12':(text.includes('SIGNAL')||text.startsWith('SIGN ')?'#1b5fa6':'#b5252b')),width:assetData?0:2,fill:'#fff',fillOpacity:assetData?0:1,dash:'',hatch:'none',hatchColor:'#000',hatchSpacing:10,opacity:1,rotation:0})}
function svgAspectFromText(text){const vb=text.match(/viewBox\s*=\s*["']\s*[-+0-9.eE]+[ ,]+[-+0-9.eE]+[ ,]+([-+0-9.eE]+)[ ,]+([-+0-9.eE]+)\s*["']/i);if(vb){const w=Math.abs(Number(vb[1])),h=Math.abs(Number(vb[2]));if(w&&h)return w/h}const wm=text.match(/\bwidth\s*=\s*["']([0-9.]+)(?:px|pt)?["']/i),hm=text.match(/\bheight\s*=\s*["']([0-9.]+)(?:px|pt)?["']/i);if(wm&&hm&&Number(hm[1]))return Number(wm[1])/Number(hm[1]);return 1}
