function imageAspect(data){return new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im.naturalWidth&&im.naturalHeight?im.naturalWidth/im.naturalHeight:1);im.onerror=()=>resolve(1);im.src=data})}
$('#addCustomStamp').onclick=()=>$('#stampOpen').click();$('#stampOpen').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;const data=await fileDataUrl(f),aspect=await imageAspect(data);state.customStamps.push({name:f.name,data,aspect});try{localStorage.setItem('nxt_custom_stamps',JSON.stringify(state.customStamps))}catch{toast('Custom stamp added for this session; browser storage is full.')}renderCustomStamps();toast('Custom stamp artwork added to local library.')};
function trafficPreview(s){if(s.svg){const src=encodeURI(MUTCD_ASSET_BASE+s.svg);return`<div class="trafficSignPreview asset"><img class="mutcdThumb" src="${src}" alt="${esc(s.code)} ${esc(s.name)}"></div>`}const cls=s.shape==='diamond'?'diamond '+(s.background==='orange'?'orange':''):s.shape==='octagon'?'octagon':s.shape==='triangle'?'triangle':'rectangle '+(s.background==='green'?'green':s.background==='blue'?'blue':'');const text=(s.shape==='octagon'?'STOP':s.shape==='triangle'?'YIELD':s.name).split(/\s+/).slice(0,4).join(' ');return`<div class="trafficSignPreview"><div class="face ${cls}"><span>${esc(text)}</span></div></div>`}
function federalCategoryFor(code,meta){if(/^W(20|21|22|23|24|25|26)-/i.test(code))return'ttc';return meta.category||'other'}
function normalizeTrafficSearch(v){return String(v||'').toLowerCase().replace(/([a-z]+)(0*)(\d+)/g,(_,a,z,n)=>a+String(Number(n))).replace(/-(0+)(\d+)/g,'-$2').replace(/\s+/g,' ').trim()}
function localText(url){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('GET',url,true);x.onreadystatechange=()=>{if(x.readyState!==4)return;if(x.status===200||x.status===0)resolve(x.responseText);else reject(new Error('HTTP '+x.status))};x.onerror=()=>reject(new Error('Could not load '+url));x.send()})}
async function localJson(url){return JSON.parse(await localText(url))}
async function ensureMutcdLibrary(){if(state.mutcdIndex)return state.mutcdIndex;if(state.mutcdLoad)return state.mutcdLoad;state.mutcdLoad=(async()=>{try{const j=await localJson(new URL(MUTCD_ASSET_BASE+'index.json',location.href).href);state.mutcdIndex=Object.entries(j).map(([code,m])=>({code,name:m.name,category:federalCategoryFor(code,m),rawCategory:m.category,shape:m.shape,background:m.background,svg:m.svg,itemKind:'sign',source:'FHWA MUTCD 11th Ed. / 2024 Standard Highway Signs'}));return state.mutcdIndex}catch(err){console.error('Real MUTCD SVG library not found. Generated federal fallback signs are disabled.',err);state.mutcdIndex=[];return state.mutcdIndex}})();return state.mutcdLoad}
async function renderTrafficLibrary(){const q=($('#trafficSearch').value||'').trim().toLowerCase(),cat=$('#trafficCategory').value,box=$('#trafficResults');box.innerHTML='<div class="trafficLoading">Loading traffic-control library…</div>';const full=await ensureMutcdLibrary();if(!box.isConnected)return;let items=[];full.forEach(s=>items.push(s));TRAFFIC_DEVICES.forEach(s=>items.push({...s,category:'devices',itemKind:'device',source:'2025 TMUTCD Part 6 / TxDOT work-zone standards'}));TXDOT_STANDARDS.forEach(s=>items.push({...s,category:'standards',itemKind:'standard',source:'Current TxDOT Traffic Standards'}));const nq=normalizeTrafficSearch(q);items=items.filter(s=>(cat==='all'||s.category===cat)&&(!q||`${s.code} ${s.name} ${s.source||''} ${s.group||''}`.toLowerCase().includes(q)||normalizeTrafficSearch(`${s.code} ${s.name} ${s.source||''} ${s.group||''}`).includes(nq)));const limited=items.slice(0,250);box.innerHTML='';if(full.length){const badge=document.createElement('div');badge.className='trafficLibraryBadge';badge.textContent=`REAL MUTCD SVG library loaded: ${full.length.toLocaleString()} vector sign faces`;box.appendChild(badge)}else{const err=document.createElement('div');err.className='trafficAssetError';err.innerHTML='<strong>Real MUTCD SVG assets are not loaded.</strong><span>The real MUTCD asset folder is not present beside the app. Run VERIFY_MUTCD_ASSETS.bat to confirm the local library. Generated fallback federal signs are disabled in this build.</span>';box.appendChild(err)}limited.forEach(s=>{const b=document.createElement('button');if(s.itemKind==='sign'){b.className='trafficCard assetCard';b.innerHTML=trafficPreview(s)+`<span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.source||'')}</small></span>`;b.onclick=()=>addTrafficSign(s)}else if(s.itemKind==='device'){const glyph={cone:'▲',drum:'▥',verticalPanel:'▯',barricade:'☷',barrier:'▰',arrowBoard:'⇢',pcms:'▣',tma:'▱',flagger:'⚑',workVehicle:'▣',trafficFlow:'➜',workZone:'▧',buffer:'⋯'}[s.kind]||'◆';b.className='trafficCard deviceCard';b.innerHTML=`<span class="deviceGlyph">${glyph}</span><span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.source)}</small></span>`;b.onclick=()=>addTrafficDevice(s)}else{b.className='trafficCard standardCard';b.innerHTML=`<span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.detail||s.source||'')}</small></span>`;b.onclick=()=>addStandardNote(s)}box.appendChild(b)});const foot=document.createElement('div');foot.className='trafficMore';foot.textContent=`${items.length} matching item${items.length===1?'':'s'}${items.length>limited.length?` · showing first ${limited.length}`:''} · search by sign code or description`;box.appendChild(foot)}
