function fileDataUrl(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
$('#btnOpen').onclick=()=>$('#fileOpen').click();
$('#fileOpen').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.name.toLowerCase().endsWith('.nxp')){await loadProject(JSON.parse(await f.text()));return}if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')){toast('Loading PDF pages…');await loadPdfBytes(new Uint8Array(await f.arrayBuffer()),f.name);closePalettes();setTool('hand');toast(`Opened ${state.pages.length}-page PDF for review.`);return}if(f.type.startsWith('image/')){$('#imageOpen').files=e.target.files;$('#imageOpen').dispatchEvent(new Event('change'))}}catch(err){console.error(err);toast('Open failed: '+(err.message||err))}};
async function saveProject(){finishInlineEdit();const data={format:'NXT Gen Plans Project',version:'0.1-R3',projectName:state.projectName,pages:state.pages,preset:state.preset,layers:state.layers,activeLayer:state.activeLayer,sourcePdf:state.pdfBytes?{name:state.pdfFileName||state.projectName,base64:bytesToBase64(state.pdfBytes)}:null};download(new Blob([JSON.stringify(data)],{type:'application/json'}),(state.projectName.replace(/\.pdf$/i,'')||'NXT_Gen_Plans')+'.nxp');toast('Editable NXT project saved.')}
$('#btnSaveProject').onclick=saveProject;
async function loadProject(d){if(!d||!Array.isArray(d.pages))return toast('Not a valid NXT project file.');const projectName=d.projectName||'NXT Gen Plans';state.projectName=projectName;state.preset={...state.preset,...(d.preset||{})};if(Array.isArray(d.layers)&&d.layers.length)state.layers=d.layers;state.activeLayer=d.activeLayer||state.layers[0]?.id||'default';state.pageIndex=0;state.selected=null;state.history=[];state.future=[];if(d.sourcePdf?.base64){toast('Restoring source PDF…');await loadPdfBytes(base64ToBytes(d.sourcePdf.base64),d.sourcePdf.name||projectName,d.pages);state.projectName=projectName;render()}else{state.pdfDoc=null;state.pdfBytes=null;state.pdfFileName=null;state.pages=d.pages;render();fitPage()}toast('Project loaded.')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2500)}
function openExportDialog(){$('#exportBackdrop').classList.remove('hidden')}
$('#btnExportPdf').onclick=openExportDialog;$('#cancelExport').onclick=()=>$('#exportBackdrop').classList.add('hidden');
$('#runExport').onclick=async()=>{finishInlineEdit();$('#exportBackdrop').classList.add('hidden');toast('Rendering flattened review PDF…');try{const pages=[],dpi=Number($('#exportDpi').value)||150,size=$('#exportSize').value,placement=$('#exportPlacement').value,scope=$('#exportPages').value,indices=scope==='current'?[state.pageIndex]:state.pages.map((_,i)=>i);for(let n=0;n<indices.length;n++){toast(`Rendering PDF page ${n+1} of ${indices.length}…`);pages.push(await rasterPage(indices[n],{dpi,size,placement}))}download(new Blob([buildPdf(pages)],{type:'application/pdf'}),(state.projectName.replace(/\.[^.]+$/,'')||'NXT_Gen_Plans')+'_review.pdf');toast('Adobe-compatible review PDF exported.')}catch(err){console.error(err);toast('PDF export failed: '+(err.message||err))}};
function outputSizeFor(p,size){if(!size||size==='source')return{w:p.w,h:p.h,name:p.name};const [w,h,name]=size.split(',');return{w:+w,h:+h,name}}
async function drawSvgClone(ctx,p,dx,dy,dw,dh,pdfOnlyOverlay=false){const svg=$('#pageSvg').cloneNode(true);svg.querySelector('#interactionLayer').innerHTML='';svg.setAttribute('viewBox',`0 0 ${p.w} ${p.h}`);svg.setAttribute('width',dw);svg.setAttribute('height',dh);if(pdfOnlyOverlay){const paper=svg.querySelector('.paper');if(paper)paper.setAttribute('fill','none');const bg=svg.querySelector('#backgroundLayer');if(bg)bg.innerHTML=''}const xml=new XMLSerializer().serializeToString(svg),blob=new Blob([xml],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(new Error('Could not rasterize NXT markup overlay'));img.src=url});ctx.drawImage(img,dx,dy,dw,dh);URL.revokeObjectURL(url)}
async function rasterPage(i,opts={}){const prev=state.pageIndex,sel=state.selected;state.pageIndex=i;state.selected=null;render();await new Promise(r=>setTimeout(r,30));const p=currentPage(),out=outputSizeFor(p,opts.size),dpi=opts.dpi||150;let pxPerPt=dpi/72,maxPixels=38_000_000,pixels=out.w*out.h*pxPerPt*pxPerPt;if(pixels>maxPixels)pxPerPt*=Math.sqrt(maxPixels/pixels);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(out.w*pxPerPt));c.height=Math.max(1,Math.round(out.h*pxPerPt));const ctx=c.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);const fitScale=Math.min(out.w/p.w,out.h/p.h),scale=opts.placement==='actual'?1:(opts.placement==='shrink'?Math.min(1,fitScale):fitScale),dw=p.w*scale*pxPerPt,dh=p.h*scale*pxPerPt,dx=(c.width-dw)/2,dy=(c.height-dh)/2;if(p.source?.type==='pdf'&&state.pdfDoc){const pg=await state.pdfDoc.getPage(p.source.pageNumber),vp=pg.getViewport({scale:pxPerPt*scale,rotation:p.rotation||0}),tmp=document.createElement('canvas');tmp.width=Math.max(1,Math.round(vp.width));tmp.height=Math.max(1,Math.round(vp.height));await pg.render({canvasContext:tmp.getContext('2d',{alpha:false}),viewport:vp}).promise;ctx.drawImage(tmp,dx,dy,dw,dh);await drawSvgClone(ctx,p,dx,dy,dw,dh,true)}else await drawSvgClone(ctx,p,dx,dy,dw,dh,false);const jpg=base64Bytes(c.toDataURL('image/jpeg',.94).split(',')[1]);state.pageIndex=prev;state.selected=sel;render();return{w:out.w,h:out.h,jpg,iw:c.width,ih:c.height}}
function base64Bytes(s){const bin=atob(s),a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a}
function buildPdf(pages){const enc=new TextEncoder(),parts=[],offsets=[0];let len=0;const push=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);len+=b.length};push('%PDF-1.7\n%âãÏÓ\n');const objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';const kids=[];let obj=3;for(const p of pages){const pageObj=obj++,contentObj=obj++,imgObj=obj++;kids.push(`${pageObj} 0 R`);objects[pageObj]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${p.w} ${p.h}] /Resources << /XObject << /Im0 ${imgObj} 0 R >> >> /Contents ${contentObj} 0 R >>`;const stream=`q\n${p.w} 0 0 ${p.h} 0 0 cm\n/Im0 Do\nQ\n`;objects[contentObj]={dict:`<< /Length ${enc.encode(stream).length} >>`,stream:enc.encode(stream)};objects[imgObj]={dict:`<< /Type /XObject /Subtype /Image /Width ${p.iw} /Height ${p.ih} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.jpg.length} >>`,stream:p.jpg}}objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;for(let i=1;i<objects.length;i++){offsets[i]=len;push(`${i} 0 obj\n`);const o=objects[i];if(typeof o==='string')push(o+'\nendobj\n');else{push(o.dict+'\nstream\n');push(o.stream);push('\nendstream\nendobj\n')}}const xref=len;push(`xref\n0 ${objects.length}\n0000000000 65535 f \n`);for(let i=1;i<objects.length;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const outb=new Uint8Array(len);let pos=0;for(const b of parts){outb.set(b,pos);pos+=b.length}return outb}
function setZoom(z){state.zoom=Math.max(.05,Math.min(8,z));const zt=Math.round(state.zoom*100)+'%';$('#zoomSelect').value=[...$('#zoomSelect').options].some(o=>o.value===zt)?zt:'';render()}
function fitPage(){const p=currentPage(),a=$('#canvasScroller');setZoom(Math.min((a.clientWidth-55)/(p.w*96/72),(a.clientHeight-55)/(p.h*96/72)))}function fitWidth(){const p=currentPage(),a=$('#canvasScroller');setZoom((a.clientWidth-45)/(p.w*96/72))}
$('#zoomIn').onclick=()=>setZoom(state.zoom*1.25);$('#zoomOut').onclick=()=>setZoom(state.zoom/1.25);$('#fitPage').onclick=fitPage;$('#fitWidth').onclick=fitWidth;$('#actualSize').onclick=()=>setZoom(1);$('#zoomSelect').onchange=e=>{const n=parseFloat(e.target.value);if(n)setZoom(n/100)};
const sc=$('#canvasScroller');sc.addEventListener('pointerdown',e=>{if(state.tool!=='hand'||e.button!==0)return;state.pan={x:e.clientX,y:e.clientY,l:sc.scrollLeft,t:sc.scrollTop};sc.classList.add('panning');e.preventDefault()});window.addEventListener('pointermove',e=>{if(!state.pan)return;sc.scrollLeft=state.pan.l-(e.clientX-state.pan.x);sc.scrollTop=state.pan.t-(e.clientY-state.pan.y)});window.addEventListener('pointerup',()=>{state.pan=null;sc.classList.remove('panning')});sc.addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();const old=state.zoom,r=sc.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;setZoom(state.zoom*(e.deltaY<0?1.12:.89));const ratio=state.zoom/old;sc.scrollLeft=(sc.scrollLeft+mx)*ratio-mx;sc.scrollTop=(sc.scrollTop+my)*ratio-my}},{passive:false});
function updateStatus(){const p=currentPage();$('#statusPage').textContent=`Page ${state.pageIndex+1} / ${state.pages.length}`;$('#statusSize').textContent=p.name;$('#statusZoom').textContent=Math.round(state.zoom*100)+'%';$('#docTitle').textContent=state.projectName}

function copySelected(){const m=selectedMarkup();if(!m)return toast('Select a markup first.');state.clipboard=JSON.parse(JSON.stringify(m));toast('Markup copied.')}
function pasteSelected(){if(!state.clipboard)return toast('Nothing copied.');checkpoint();const c=JSON.parse(JSON.stringify(state.clipboard)),orig=JSON.parse(JSON.stringify(state.clipboard));c.id=uid();translateMarkup(c,16,16,orig);c.subject=(c.subject||'Markup')+' Copy';c.created=c.modified=new Date().toISOString();currentPage().markups.push(c);state.selected=c.id;render();setTool('select')}
function nextPage(delta){const n=Math.max(0,Math.min(state.pages.length-1,state.pageIndex+delta));if(n===state.pageIndex)return;state.pageIndex=n;state.selected=null;render();fitPage()}
function duplicatePage(){checkpoint();const p=JSON.parse(JSON.stringify(currentPage()));p.id=uid();p.markups.forEach(m=>m.id=uid());state.pages.splice(state.pageIndex+1,0,p);state.pageIndex++;state.selected=null;render();fitPage()}
function deletePage(){if(state.pages.length<=1)return toast('A document must contain at least one page.');checkpoint();state.pages.splice(state.pageIndex,1);state.pageIndex=Math.min(state.pageIndex,state.pages.length-1);state.selected=null;render();fitPage()}
function rotatePoint90(x,y,h){return[h-y,x]}
function rotateMarkup90(m,h){if(LINE_TYPES.includes(m.type)){[m.x,m.y]=rotatePoint90(m.x,m.y,h);[m.x2,m.y2]=rotatePoint90(m.x2,m.y2,h)}else if(POLY_TYPES.includes(m.type)||m.type==='freehand'){m.points=m.points.map(([x,y])=>rotatePoint90(x,y,h));if(m.type==='freehand')rebuildFreehand(m)}else{const pts=[[m.x,m.y],[m.x+(m.w||0),m.y],[m.x+(m.w||0),m.y+(m.h||0)],[m.x,m.y+(m.h||0)]].map(([x,y])=>rotatePoint90(x,y,h)),xs=pts.map(a=>a[0]),ys=pts.map(a=>a[1]);m.x=Math.min(...xs);m.y=Math.min(...ys);m.w=Math.max(...xs)-m.x;m.h=Math.max(...ys)-m.y}m.rotation=((m.rotation||0)+90)%360}
function rotateCurrentPage(dir=1){checkpoint();const p=currentPage(),times=dir>0?1:3;for(let n=0;n<times;n++){const oldH=p.h;p.markups.forEach(m=>rotateMarkup90(m,oldH));[p.w,p.h]=[p.h,p.w];p.rotation=((p.rotation||0)+90)%360}render();fitPage()}
function highlightTextSelection(){const sel=window.getSelection();if(!sel||sel.isCollapsed)return toast('Select PDF text first.');const stage=$('#pageStage').getBoundingClientRect(),sc=96/72*state.zoom,rects=[...sel.getRangeAt(0).getClientRects()].filter(r=>r.width>1&&r.height>1);if(!rects.length)return toast('No text selection found.');checkpoint();for(const r of rects){const x=(r.left-stage.left)/sc,y=(r.top-stage.top)/sc,w=r.width/sc,h=r.height/sc;if(x<currentPage().w&&y<currentPage().h&&x+w>0&&y+h>0){currentPage().markups.push({...baseMarkup('highlight',{x,y}),x,y,w,h,fill:'#ffe000',fillOpacity:.42,stroke:'none',width:0,subject:'Text Highlight',layer:'comments'})}}sel.removeAllRanges();render();setTool('select');toast('Text selection highlighted.')}
